args.new_string:
import { getNotificationPreference, toggleNotificationPreference } from './actions'

export default async function Home() {
  // In a real app, you'd get the userId from auth session
  const userId = 'demo-user'

  // Fetch current notification preference
  const notificationsEnabled = await getNotificationPreference(userId)

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Settings</h1>

      <div style={{ marginTop: '2rem' }}>
        <form action={toggleNotificationPreference.bind(null, userId)}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
            <label htmlFor="notifications">Notifications:</label>
            <span style={{
              fontWeight: 'bold',
              color: notificationsEnabled ? 'green' : 'red'
            }}>
              {notificationsEnabled ? 'ON' : 'OFF'}
            </span>
            <button
              type="submit"
              style={{
                padding: '0.5rem 1rem',
                cursor: 'pointer',
                backgroundColor: '#0070f3',
                color: 'white',
                border: 'none',
                borderRadius: '4px'
              }}
            >
              Toggle
            </button>
          </div>
        </form>

        <p style={{ marginTop: '1rem', color: '#666' }}>
          Click the toggle button to switch notifications {notificationsEnabled ? 'off' : 'on'}.
          The page will refresh automatically to show the updated preference.
        </p>
      </div>
    </main>
  );
}

